From a6bd55ddf6f373e2b0433bec8783b231002346d6 Mon Sep 17 00:00:00 2001
From: Garrett Brown <garbearucla@gmail.com>
Date: Tue, 23 Apr 2013 06:10:12 -0700
Subject: [PATCH] Fixed mingw compile error introduced in 0a482f255:
 'm_state_enum' undeclared identifier, explicit cast isn't necessary so only
 include it when MSVC C++ fix is needed


diff --git a/NQ/menu.c b/NQ/menu.c
index a690cd9..91eabf1 100644
--- a/NQ/menu.c
+++ b/NQ/menu.c
@@ -1555,7 +1555,11 @@ M_Quit_Key(int key)
     case 'n':
     case 'N':
 	if (wasInMenus) {
+#ifdef _MSC_VER
 	    m_state = (m_state_enum)m_quit_prevstate;
+#else
+	    m_state = m_quit_prevstate;
+#endif
 	    m_entersound = true;
 	} else {
 	    key_dest = key_game;
@@ -1584,7 +1588,11 @@ static void
 M_Quit_Draw(void)
 {
     if (wasInMenus) {
+#ifdef _MSC_VER
 	m_state = (m_state_enum)m_quit_prevstate;
+#else
+	m_state = m_quit_prevstate;
+#endif
 	m_recursiveDraw = true;
 	M_Draw();
 	m_state = m_quit;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the introduction of an undeclared identifier `m_state_enum` in a previous commit, which led to compilation errors when using the MSVC compiler. The explicit cast to `m_state_enum` was unnecessary for other compilers, resulting in a need for conditional compilation to handle the differences between MSVC and other compilers.

        Commit message:
        Fixed mingw compile error introduced in 0a482f255:
 'm_state_enum' undeclared identifier, explicit cast isn't necessary so only
 include it when MSVC C++ fix is needed  

        Patch:

 static void
 M_Quit_Key(int key)
 {
 #if 0
     switch (key) {
     case K_ESCAPE:
     case 'n':
     case 'N':
 	if (wasInMenus) {
+#ifdef _MSC_VER
 	    m_state = (m_state_enum)m_quit_prevstate;
+#else
+	    m_state = m_quit_prevstate;
+#endif
 	    m_entersound = true;
 	} else {
 	    key_dest = key_game;
 	    m_state = m_none;
 	}
 	break;

     case 'Y':
     case 'y':
 	key_dest = key_console;
 	Host_Quit_f();
 	break;

     default:
 	break;
     }
 #else
 	key_dest = key_console;
 	Host_Quit_f();
    environ_cb(RETRO_ENVIRONMENT_SHUTDOWN, NULL);
 #endif
 }


 static void
 M_Quit_Draw(void)
 {
     if (wasInMenus) {
+#ifdef _MSC_VER
 	m_state = (m_state_enum)m_quit_prevstate;
+#else
+	m_state = m_quit_prevstate;
+#endif
 	m_recursiveDraw = true;
 	M_Draw();
 	m_state = m_quit;
     }

     M_DrawTextBox(56, 76, 24, 4);
     M_Print(64, 84, quitMessage[msgNumber * 4 + 0]);
     M_Print(64, 92, quitMessage[msgNumber * 4 + 1]);
     M_Print(64, 100, quitMessage[msgNumber * 4 + 2]);
     M_Print(64, 108, quitMessage[msgNumber * 4 + 3]);
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>
